﻿using Keycloak.AuthServices.Authorization;
using Microsoft.AspNetCore.Authorization;

namespace Lecos.Strassennamen.RestAPI.Authorization;

public static class AuthorizationBuilderExtensions
{
    public static AuthorizationBuilder ConfigureAuthorization(this AuthorizationBuilder builder, string client)
    {
        var allClientRoles = AuthorizationUtils.GetStringConstantsFrom(typeof(ClientRoles));
        foreach (var clientRole in allClientRoles)
        {
            builder.AddPolicy(
                clientRole,
                policy => policy.RequireResourceRolesForClient(client, [clientRole])
            );
        }

        return builder;
    }
}﻿using System.Reflection;

namespace Lecos.Strassennamen.RestAPI.Authorization;

public static class AuthorizationUtils
{
    public static List<string> GetStringConstantsFrom(Type type)
    {
        return type
            .GetFields(BindingFlags.Public | BindingFlags.Static | BindingFlags.FlattenHierarchy)
            .Where(x => x.IsLiteral)
            .Select(x => x.GetValue(null))
            .OfType<string>()
            .ToList();
    }
}﻿namespace Lecos.Strassennamen.RestAPI.Authorization;

public static class ClientRoles
{
    public const string AppAccess = "app-access";
    public const string Editor = "editor";
}
